import java.util.*;

record Book(long id, String title) { }

interface BookRepository {
    Optional<Book> findById(long id);
}

public class Main {
    public static void main(String[] a) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        Map<Long, Book> data = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long id = s.nextLong();
            data.put(id, new Book(id, s.next()));
        }
        long target = s.nextLong();
        BookRepository repo = id -> Optional.ofNullable(data.get(id));
        String out = repo.findById(target).map(b -> b.id() + ":" + b.title()).orElse("NOT_FOUND");
        System.out.println(out);
    }
}

