import java.util.*;

record Book(long id, String title) { }

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        List<Book> books = new ArrayList<>();
        for (int i = 0; i < n; i++) books.add(new Book(s.nextLong(), s.next()));
        String sort = s.next();
        int page = s.nextInt(), size = s.nextInt();
        books.sort(sort.equals("id") ? Comparator.comparingLong(Book::id) : Comparator.comparing(Book::title));
        int from = (page - 1) * size, to = Math.min(from + size, n);
        if (from >= n || from < 0) System.out.println("EMPTY_PAGE");
        else for (Book b : books.subList(from, to)) System.out.println(b.id() + ":" + b.title());
        System.out.println("PAGES " + (n + size - 1) / size);
    }
}

