import java.time.*;
import java.time.format.*;
import java.util.*;

record Request(String name, String email, String password, String createdAt) { }

public class Main {
    static String violation(Request r) {
        if (r.name().equals("-")) return "name";
        if (!r.email().contains("@")) return "email";
        if (r.password().length() < 8) return "password";
        try {
            Instant.parse(r.createdAt());
        } catch (DateTimeParseException e) {
            return "createdAt";
        }
        return null;
    }

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        ZoneId zone = ZoneId.of(s.next());
        int n = s.nextInt();
        List<Request> requests = new ArrayList<>();
        for (int i = 0; i < n; i++) requests.add(new Request(s.next(), s.next(), s.next(), s.next()));
        for (int k = 1; k <= n; k++) {
            Request r = requests.get(k - 1);
            String bad = violation(r);
            if (bad != null) System.out.println("400 " + k + " " + bad);
            else System.out.println("201 " + k + " " + Instant.parse(r.createdAt()).atZone(zone).toLocalDate().format(DateTimeFormatter.ISO_LOCAL_DATE));
        }
        for (int k = 1; k <= n; k++) {
            Request r = requests.get(k - 1);
            System.out.println("LOG " + k + " name=" + r.name() + " email=" + r.email() + " password=[REDACTED]");
        }
    }
}
